const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const host = document.createElement("p");
host.className = "mo-k-line " + (total > 12 ? "mo-k-small" : "mo-k-large");
ctx.root.append(host);
const nodes = ctx.words.map((word) => {
  const node = document.createElement("span");
  node.className = "mo-k-word";
  node.textContent = word.text;
  host.append(node);
  return node;
});
const longest = ctx.words.reduce((best, word) => (word.text.length > ctx.words[best].text.length ? word.index : best), 0);
nodes[longest].classList.add("mo-k-key");
nodes.forEach((node, index) => {
  ctx.timeline.from(
    node,
    { opacity: 0, y: 44, duration: 0.35, ease: "power3.out" },
    Math.min(ctx.at(index), latest),
  );
});
const rule = document.createElement("div");
rule.className = "mo-k-rule";
ctx.root.append(rule);
ctx.timeline.from(rule, { scaleX: 0, duration: 0.6, ease: "power2.inOut" }, cue(0.9));

