.mo-s-{{sceneId}} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-k-line {
  margin: 0;
  max-width: 100%;
  text-align: center;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}
.mo-s-{{sceneId}} .mo-k-large {
  font-size: var(--mo-text-title);
}
.mo-s-{{sceneId}} .mo-k-small {
  font-size: var(--mo-text-subtitle);
}
.mo-s-{{sceneId}} .mo-k-word {
  display: inline-block;
  margin-inline: 0.14em;
}
.mo-s-{{sceneId}} .mo-k-key {
  color: var(--mo-accent);
}
.mo-s-{{sceneId}} .mo-k-rule {
  width: calc(var(--mo-unit) * 18);
  height: calc(var(--mo-unit) * 0.9);
  margin-top: calc(var(--mo-unit) * 4);
  border-radius: 999px;
  background: var(--mo-accent);
  transform-origin: left center;
}
